"""
Mo-dun quan ly hinh anh mau (Templates) va tai nguyen nhung cho Auto Rally.
Ho tro 4 he thong mau phu hop 4 goc lanh tho (Vang, Xanh, Do, Tim) tren Mapview.
Tu dong giai ma chuoi Base64 thanh mang hinh anh OpenCV va luu bo nho dem (cache).
"""

import base64
from typing import List, Tuple, Optional
import cv2
import numpy as np

# Template tieu de 'Tong Tan Cong!' - Phe Yellow
RALLY_HEADER_YELLOW_B64: str = """"""

# Template tieu de 'Tong Tan Cong!' - Phe Blue
RALLY_HEADER_BLUE_B64: str = """"""

# Template tieu de 'Tong Tan Cong!' - Phe Red
RALLY_HEADER_RED_B64: str = """"""

# Template tieu de 'Tong Tan Cong!' - Phe Purple
RALLY_HEADER_PURPLE_B64: str = """"""


# Cache danh sach template da giai ma trong RAM de khong phai decode lap lai
_cached_templates: Optional[List[Tuple[str, np.ndarray]]] = None


def get_rally_templates() -> List[Tuple[str, np.ndarray]]:
    """
    Tra ve danh sach cac hinh anh mau tieu de Rally cho ca 4 phe dia hinh:
    [('yellow', tpl), ('blue', tpl), ('red', tpl), ('purple', tpl)]
    """
    global _cached_templates
    if _cached_templates is None:
        templates = []
        raw_map = [
            ("yellow", RALLY_HEADER_YELLOW_B64),
            ("blue", RALLY_HEADER_BLUE_B64),
            ("red", RALLY_HEADER_RED_B64),
            ("purple", RALLY_HEADER_PURPLE_B64),
        ]
        for name, b64_str in raw_map:
            raw_bytes = base64.b64decode(b64_str)
            tpl = cv2.imdecode(np.frombuffer(raw_bytes, dtype=np.uint8), cv2.IMREAD_COLOR)
            if tpl is not None:
                templates.append((name, tpl))
        _cached_templates = templates
    return _cached_templates


def get_rally_template() -> np.ndarray:
    """Tuong thich nguoc: Tra ve template phe vang mac dinh."""
    tpls = get_rally_templates()
    return tpls[0][1] if tpls else None

# ==============================================================================
# TEMPLATES FOR AUTO PHIEU LUU CO VAT
# ==============================================================================
PHIEULUU_BAT_DAU_B64: str = """"""

PHIEULUU_TIEN_LEN_B64: str = """"""

PHIEULUU_CHIEN_DAU_B64: str = """"""

PHIEULUU_CHAP_NHAN_B64: str = """"""

PHIEULUU_CHAM_TIEP_TUC_B64: str = """"""


_cached_phieuluu_templates: Optional[dict] = None

PHIEULUU_TIEP_TUC_B64 = ""

def get_phieuluu_templates() -> dict:
    """
    Tra ve dictionary cac template cho Auto Phieu Luu Co Vat:
    {'bat_dau': tpl, 'tien_len': tpl, 'chien_dau': tpl, 'chap_nhan': tpl, 'cham_tiep_tuc': tpl}
    Uu tien doc tu thu muc assets_phieuluu/, neu khong co se tu decode chuoi Base64 nhung.
    """
    global _cached_phieuluu_templates
    if _cached_phieuluu_templates is not None:
        return _cached_phieuluu_templates
    
    import os
    res = {}
    names = ['bat_dau', 'tien_len', 'chien_dau', 'chap_nhan', 'cham_tiep_tuc', 'tiep_tuc']
    base_dir = os.path.join(os.path.dirname(__file__), 'assets_phieuluu')
    
    raw_b64_map = {
        'bat_dau': PHIEULUU_BAT_DAU_B64,
        'tien_len': PHIEULUU_TIEN_LEN_B64,
        'chien_dau': PHIEULUU_CHIEN_DAU_B64,
        'chap_nhan': PHIEULUU_CHAP_NHAN_B64,
        'cham_tiep_tuc': PHIEULUU_CHAM_TIEP_TUC_B64,
        'tiep_tuc': PHIEULUU_TIEP_TUC_B64,
    }
    
    for n in names:
        file_path = os.path.join(base_dir, f'{n}.png')
        if os.path.isfile(file_path):
            tpl = cv2.imread(file_path)
        else:
            tpl = None
        if tpl is None and n in raw_b64_map:
            raw_bytes = base64.b64decode(raw_b64_map[n])
            tpl = cv2.imdecode(np.frombuffer(raw_bytes, dtype=np.uint8), cv2.IMREAD_COLOR)
        if tpl is not None:
            res[n] = tpl
            
    _cached_phieuluu_templates = res
    return _cached_phieuluu_templates
